import json
import re
from typing import Dict, List, Set, Any, Optional
from dataclasses import dataclass
from enum import Enum

class PermissionLevel(Enum):
    READ = "read"
    WRITE = "write"
    DELETE = "delete"
    ADMIN = "admin"

@dataclass
class User:
    user_id: str
    username: str
    roles: Set[str]
    permissions: Set[PermissionLevel]

@dataclass
class Role:
    role_id: str
    name: str
    permissions: Set[PermissionLevel]
    resources: Set[str]

@dataclass
class Resource:
    resource_id: str
    name: str
    type: str
    owner: str

class InputSanitizer:
    """Handles input sanitization to prevent injection attacks"""

    @staticmethod
    def sanitize_string(input_str: str) -> str:
        """Remove potentially dangerous characters from string input"""
        if not isinstance(input_str, str):
            return str(input_str)

        # Remove common SQL injection patterns
        dangerous_patterns = [
            r"(\b(union|select|insert|update|delete|drop|create|alter)\b)",
            r"(\b(--|/\*|\*/)\b)",
            r"(\b(exec|execute)\b)",
            r"(\b(declare|set)\b)"
        ]

        sanitized = input_str
        for pattern in dangerous_patterns:
            sanitized = re.sub(pattern, "", sanitized, flags=re.IGNORECASE)

        # Remove HTML/JS tags
        sanitized = re.sub(r"<[^>]*>", "", sanitized)

        return sanitized.strip()

    @staticmethod
    def sanitize_json(data: Dict[str, Any]) -> Dict[str, Any]:
        """Sanitize JSON data recursively"""
        if not isinstance(data, dict):
            return data

        sanitized = {}
        for key, value in data.items():
            if isinstance(value, str):
                sanitized[InputSanitizer.sanitize_string(key)] = InputSanitizer.sanitize_string(value)
            elif isinstance(value, dict):
                sanitized[InputSanitizer.sanitize_string(key)] = InputSanitizer.sanitize_json(value)
            elif isinstance(value, list):
                sanitized[InputSanitizer.sanitize_string(key)] = [InputSanitizer.sanitize_json(item) if isinstance(item, dict) else item for item in value]
            else:
                sanitized[InputSanitizer.sanitize_string(key)] = value

        return sanitized

